-- ============================================================
-- 018: Notes (offline-first, Google Keep style)
--
-- Browsers keep notes in IndexedDB (Dexie) and sync them here through
-- POST /api/notes/sync. This migration is ADDITIVE: it creates new objects only and
-- changes nothing that already exists. Take a backup before running on production.
--
-- Design
--   * id is generated by the client (UUID) so notes can be created offline.
--   * `version` + `field_revs` give per-field optimistic concurrency: two devices that edit
--     DIFFERENT fields of a note merge cleanly; a real conflict on title/content NEVER
--     overwrites - the server keeps its text and the other device's text is saved as a
--     separate "(conflict copy)" note.
--   * Deletes are soft (tombstone via deleted_at) so other devices learn about them.
--   * note_mutations makes retries idempotent (a lost response never double-applies).
--   * Writes happen ONLY through the SECURITY INVOKER functions below, which the API calls
--     with the service role after authenticating the user. Browsers get read-only (RLS)
--     access to their own rows; the functions are NOT executable by anon/authenticated,
--     otherwise a user could call them with someone else's user id.
-- ============================================================

CREATE TABLE IF NOT EXISTS notes (
  id                uuid        PRIMARY KEY,
  user_id           uuid        NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  title             text        NOT NULL DEFAULT ''        CHECK (char_length(title)   <= 500),
  content           text        NOT NULL DEFAULT ''        CHECK (char_length(content) <= 100000),
  color             text        NOT NULL DEFAULT 'default'
                    CHECK (color IN ('default','red','orange','yellow','green','teal','blue','purple','pink','gray')),
  labels            text[]      NOT NULL DEFAULT '{}'      CHECK (cardinality(labels) <= 20),
  pinned            boolean     NOT NULL DEFAULT false,
  archived          boolean     NOT NULL DEFAULT false,
  deleted_at        timestamptz,
  version           integer     NOT NULL DEFAULT 1,
  field_revs        jsonb       NOT NULL DEFAULT '{}'::jsonb,
  client_updated_at timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX IF NOT EXISTS notes_user_sync_idx ON notes (user_id, updated_at, id);

CREATE TABLE IF NOT EXISTS note_mutations (
  mutation_id uuid        PRIMARY KEY,
  user_id     uuid        NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  note_id     uuid        NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS note_mutations_created_idx ON note_mutations (created_at);

-- updated_at uses clock_timestamp() (not now()) so every row written in one transaction still gets a
-- distinct, increasing value - the sync cursor is (updated_at, id). Ownership can never change.
CREATE OR REPLACE FUNCTION notes_before_write() RETURNS trigger
LANGUAGE plpgsql AS $fn$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'notes.user_id is immutable';
  END IF;
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END
$fn$;

DROP TRIGGER IF EXISTS trg_notes_before_write ON notes;
CREATE TRIGGER trg_notes_before_write BEFORE INSERT OR UPDATE ON notes
  FOR EACH ROW EXECUTE FUNCTION notes_before_write();

-- ── Row Level Security: read-only for the owner; all writes go through the functions ──
ALTER TABLE notes          ENABLE ROW LEVEL SECURITY;
ALTER TABLE note_mutations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "notes_select_own" ON notes;
CREATE POLICY "notes_select_own" ON notes FOR SELECT USING (auth.uid() = user_id);

REVOKE ALL ON notes          FROM anon, authenticated;
REVOKE ALL ON note_mutations FROM anon, authenticated;
GRANT SELECT ON notes TO authenticated;
-- The API uses the service role (explicit so this works on any Postgres, not only via Supabase's default privileges).
GRANT ALL ON notes, note_mutations TO service_role;

-- ── JSON shape returned to clients ──────────────────────────
CREATE OR REPLACE FUNCTION notes_public(r notes) RETURNS jsonb
LANGUAGE sql STABLE AS $fn$
  SELECT jsonb_build_object(
    'id', r.id, 'title', r.title, 'content', r.content, 'color', r.color,
    'labels', to_jsonb(r.labels), 'pinned', r.pinned, 'archived', r.archived,
    'deleted', r.deleted_at IS NOT NULL, 'version', r.version,
    'created_at', r.created_at, 'updated_at', r.updated_at)
$fn$;

-- canonical label set: distinct, byte-order sorted (matches the client's default sort)
CREATE OR REPLACE FUNCTION notes_canon_labels(p_labels text[]) RETURNS text[]
LANGUAGE sql IMMUTABLE AS $fn$
  SELECT coalesce(array_agg(x ORDER BY x COLLATE "C"), '{}'::text[])
  FROM (SELECT DISTINCT unnest(p_labels) AS x) s
$fn$;

-- ── Apply ONE client mutation ───────────────────────────────
-- p_m = { mutation_id, id, base_version, dirty:[field...], note:{full client values}, copy_id?, client_updated_at? (ms) }
-- Returns { mutation_id, status: applied|conflict|duplicate|rejected, note?, copy?, conflicts?, restored?, error? }
CREATE OR REPLACE FUNCTION notes_apply_mutation(p_user uuid, p_m jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public AS $fn$
DECLARE
  v_mid uuid; v_id uuid; v_base int; v_dirty text[]; v_note jsonb; v_copy uuid; v_cts timestamptz;
  v_title text; v_content text; v_color text; v_labels text[]; v_pinned boolean; v_archived boolean; v_deleted boolean;
  r notes%ROWTYPE; c notes%ROWTYPE;
  v_dup_user uuid;
  f text; v_rev int; v_attempt int := 0;
  n_title text; n_content text; n_color text; n_labels text[]; n_pinned boolean; n_archived boolean; n_deleted boolean;
  v_changed text[] := '{}'; v_conflicts text[] := '{}'; v_restored boolean := false;
  v_revs jsonb; v_new_ver int; v_client_newer boolean; v_merged_labels text[];
  v_copy_json jsonb := NULL;
  v_all_revs constant jsonb := '{"title":1,"content":1,"color":1,"labels":1,"pinned":1,"archived":1,"deleted":1}';
BEGIN
  -- 1. parse and validate (never trust the client)
  BEGIN
    v_mid   := (p_m->>'mutation_id')::uuid;
    v_id    := (p_m->>'id')::uuid;
    v_base  := coalesce((p_m->>'base_version')::int, 0);
    v_note  := p_m->'note';
    v_copy  := nullif(p_m->>'copy_id', '')::uuid;
    v_cts   := CASE WHEN p_m ? 'client_updated_at' THEN to_timestamp((p_m->>'client_updated_at')::double precision / 1000.0) END;
    v_dirty := ARRAY(SELECT jsonb_array_elements_text(coalesce(p_m->'dirty', '[]'::jsonb)));

    IF v_base < 0 OR jsonb_typeof(v_note) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'bad'; END IF;
    IF v_dirty <@ ARRAY['title','content','color','labels','pinned','archived','deleted'] IS NOT TRUE THEN RAISE EXCEPTION 'bad'; END IF;
    IF jsonb_typeof(v_note->'title')   IS DISTINCT FROM 'string' OR char_length(v_note->>'title')   > 500    THEN RAISE EXCEPTION 'bad'; END IF;
    IF jsonb_typeof(v_note->'content') IS DISTINCT FROM 'string' OR char_length(v_note->>'content') > 100000 THEN RAISE EXCEPTION 'bad'; END IF;
    IF (v_note->>'color') IS NULL OR (v_note->>'color') NOT IN ('default','red','orange','yellow','green','teal','blue','purple','pink','gray') THEN RAISE EXCEPTION 'bad'; END IF;
    IF jsonb_typeof(v_note->'labels') IS DISTINCT FROM 'array' OR jsonb_array_length(v_note->'labels') > 20 THEN RAISE EXCEPTION 'bad'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_note->'labels') e
               WHERE jsonb_typeof(e) <> 'string' OR char_length(e #>> '{}') NOT BETWEEN 1 AND 40) THEN RAISE EXCEPTION 'bad'; END IF;
    IF jsonb_typeof(v_note->'pinned')   IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(v_note->'archived') IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(v_note->'deleted')  IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'bad'; END IF;

    v_title    := v_note->>'title';
    v_content  := v_note->>'content';
    v_color    := v_note->>'color';
    v_labels   := notes_canon_labels(ARRAY(SELECT jsonb_array_elements_text(v_note->'labels')));
    v_pinned   := (v_note->>'pinned')::boolean;
    v_archived := (v_note->>'archived')::boolean;
    v_deleted  := (v_note->>'deleted')::boolean;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('mutation_id', p_m->>'mutation_id', 'status', 'rejected', 'error', 'invalid_mutation');
  END;

  -- 2. lock the row (or create it). A concurrent identical request waits here, then sees the mutation record.
  LOOP
    SELECT * INTO r FROM notes WHERE id = v_id FOR UPDATE;
    IF FOUND THEN EXIT; END IF;

    SELECT user_id INTO v_dup_user FROM note_mutations WHERE mutation_id = v_mid;
    IF FOUND THEN
      IF v_dup_user <> p_user THEN
        RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'rejected', 'error', 'forbidden');
      END IF;
      RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'duplicate');
    END IF;

    IF v_deleted THEN  -- a note created and deleted before it ever reached the server: nothing to store
      INSERT INTO note_mutations (mutation_id, user_id, note_id) VALUES (v_mid, p_user, v_id) ON CONFLICT DO NOTHING;
      RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'applied');
    END IF;

    INSERT INTO notes (id, user_id, title, content, color, labels, pinned, archived, version, field_revs, client_updated_at)
    VALUES (v_id, p_user, v_title, v_content, v_color, v_labels, v_pinned, v_archived, 1, v_all_revs, v_cts)
    ON CONFLICT (id) DO NOTHING
    RETURNING * INTO r;
    IF FOUND THEN
      INSERT INTO note_mutations (mutation_id, user_id, note_id) VALUES (v_mid, p_user, v_id) ON CONFLICT DO NOTHING;
      RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'applied', 'note', notes_public(r));
    END IF;

    v_attempt := v_attempt + 1;  -- someone inserted it between our SELECT and INSERT: loop and lock it
    IF v_attempt > 3 THEN
      RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'rejected', 'error', 'busy');
    END IF;
  END LOOP;

  -- 3. ownership: another user's note id is indistinguishable from "not allowed"
  IF r.user_id <> p_user THEN
    RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'rejected', 'error', 'forbidden');
  END IF;

  -- 4. idempotency: this exact mutation was already applied (the response was lost)
  SELECT user_id INTO v_dup_user FROM note_mutations WHERE mutation_id = v_mid;
  IF FOUND THEN
    IF v_dup_user <> p_user THEN
      RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'rejected', 'error', 'forbidden');
    END IF;
    RETURN jsonb_build_object('mutation_id', v_mid, 'status', 'duplicate', 'note', notes_public(r));
  END IF;

  -- 5. field-level merge against the server's current row
  n_title := r.title; n_content := r.content; n_color := r.color; n_labels := r.labels;
  n_pinned := r.pinned; n_archived := r.archived; n_deleted := (r.deleted_at IS NOT NULL);
  v_client_newer := v_cts IS NULL OR r.client_updated_at IS NULL OR v_cts >= r.client_updated_at;

  FOREACH f IN ARRAY v_dirty LOOP
    v_rev := coalesce((r.field_revs ->> f)::int, 1);  -- version at which the server last changed this field

    IF f = 'title' THEN
      IF n_title IS DISTINCT FROM v_title THEN
        IF v_rev <= v_base THEN n_title := v_title; v_changed := v_changed || f; ELSE v_conflicts := v_conflicts || f; END IF;
      END IF;
    ELSIF f = 'content' THEN
      IF n_content IS DISTINCT FROM v_content THEN
        IF v_rev <= v_base THEN n_content := v_content; v_changed := v_changed || f; ELSE v_conflicts := v_conflicts || f; END IF;
      END IF;
    ELSIF f = 'labels' THEN
      IF n_labels IS DISTINCT FROM v_labels THEN
        IF v_rev <= v_base THEN
          n_labels := v_labels; v_changed := v_changed || f;
        ELSE  -- both sides changed the labels: keep the union so no label is lost
          v_merged_labels := notes_canon_labels(n_labels || v_labels);
          IF v_merged_labels IS DISTINCT FROM n_labels THEN n_labels := v_merged_labels; v_changed := v_changed || f; END IF;
        END IF;
      END IF;
    ELSIF f = 'color' THEN
      IF n_color IS DISTINCT FROM v_color THEN
        IF v_rev <= v_base OR v_client_newer THEN n_color := v_color; v_changed := v_changed || f; ELSE v_conflicts := v_conflicts || f; END IF;
      END IF;
    ELSIF f = 'pinned' THEN
      IF n_pinned IS DISTINCT FROM v_pinned THEN
        IF v_rev <= v_base OR v_client_newer THEN n_pinned := v_pinned; v_changed := v_changed || f; ELSE v_conflicts := v_conflicts || f; END IF;
      END IF;
    ELSIF f = 'archived' THEN
      IF n_archived IS DISTINCT FROM v_archived THEN
        IF v_rev <= v_base OR v_client_newer THEN n_archived := v_archived; v_changed := v_changed || f; ELSE v_conflicts := v_conflicts || f; END IF;
      END IF;
    ELSIF f = 'deleted' THEN
      IF n_deleted IS DISTINCT FROM v_deleted THEN
        IF v_deleted = false THEN  -- explicit restore always wins
          n_deleted := false; v_changed := v_changed || f;
        ELSIF coalesce((r.field_revs ->> 'title')::int, 1)   > v_base
           OR coalesce((r.field_revs ->> 'content')::int, 1) > v_base
           OR coalesce((r.field_revs ->> 'labels')::int, 1)  > v_base THEN
          v_conflicts := v_conflicts || f;  -- edited elsewhere after the client last saw it: keep the note
        ELSE
          n_deleted := true; v_changed := v_changed || f;
        END IF;
      END IF;
    END IF;
  END LOOP;

  -- the client edited a note that another device deleted: bring the note back rather than lose the edit
  IF n_deleted AND NOT ('deleted' = ANY (v_dirty)) AND cardinality(v_changed) > 0
     AND coalesce((r.field_revs ->> 'deleted')::int, 1) > v_base THEN
    n_deleted := false; v_restored := true; v_changed := v_changed || 'deleted'::text;
  END IF;

  -- 6. a real text conflict: the client's text is preserved as a separate note (idempotent via copy_id)
  IF v_conflicts && ARRAY['title', 'content'] THEN
    INSERT INTO notes (id, user_id, title, content, color, labels, pinned, archived, version, field_revs, client_updated_at)
    VALUES (coalesce(v_copy, gen_random_uuid()), p_user,
            left(CASE WHEN v_title = '' THEN 'Untitled' ELSE v_title END, 480) || ' (conflict copy)',
            v_content, v_color, v_labels, false, false, 1, v_all_revs, v_cts)
    ON CONFLICT (id) DO NOTHING
    RETURNING * INTO c;
    IF NOT FOUND THEN SELECT * INTO c FROM notes WHERE id = v_copy AND user_id = p_user; END IF;
    IF c.id IS NOT NULL THEN v_copy_json := notes_public(c); END IF;
  END IF;

  -- 7. write the merged result
  IF cardinality(v_changed) > 0 THEN
    v_new_ver := r.version + 1;
    v_revs := r.field_revs;
    FOREACH f IN ARRAY v_changed LOOP
      v_revs := jsonb_set(v_revs, ARRAY[f], to_jsonb(v_new_ver));
    END LOOP;
    UPDATE notes SET
      title = n_title, content = n_content, color = n_color, labels = n_labels,
      pinned = n_pinned, archived = n_archived,
      deleted_at = CASE WHEN n_deleted THEN coalesce(r.deleted_at, now()) ELSE NULL END,
      version = v_new_ver, field_revs = v_revs,
      client_updated_at = coalesce(v_cts, r.client_updated_at)
    WHERE id = v_id
    RETURNING * INTO r;
  END IF;

  INSERT INTO note_mutations (mutation_id, user_id, note_id) VALUES (v_mid, p_user, v_id) ON CONFLICT DO NOTHING;
  IF random() < 0.01 THEN  -- cheap housekeeping: forget idempotency records older than 30 days
    DELETE FROM note_mutations WHERE created_at < now() - interval '30 days';
  END IF;

  RETURN jsonb_build_object(
    'mutation_id', v_mid,
    'status', CASE WHEN cardinality(v_conflicts) > 0 THEN 'conflict' ELSE 'applied' END,
    'note', notes_public(r),
    'copy', v_copy_json,
    'conflicts', to_jsonb(v_conflicts),
    'restored', v_restored);
END
$fn$;

-- ── Apply a batch; one bad mutation cannot poison the others ──
CREATE OR REPLACE FUNCTION notes_apply_batch(p_user uuid, p_mutations jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public AS $fn$
DECLARE m jsonb; res jsonb; out jsonb := '[]'::jsonb;
BEGIN
  FOR m IN SELECT * FROM jsonb_array_elements(coalesce(p_mutations, '[]'::jsonb)) LOOP
    BEGIN
      res := notes_apply_mutation(p_user, m);
    EXCEPTION WHEN others THEN
      res := jsonb_build_object('mutation_id', m->>'mutation_id', 'status', 'rejected', 'error', 'internal');
    END;
    out := out || jsonb_build_array(res);
  END LOOP;
  RETURN out;
END
$fn$;

-- ── Changes since a (updated_at, id) cursor, tombstones included ──
CREATE OR REPLACE FUNCTION notes_pull(p_user uuid, p_ts timestamptz, p_id uuid, p_limit int) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = public AS $fn$
  SELECT coalesce(jsonb_agg(notes_public(n) ORDER BY n.updated_at, n.id), '[]'::jsonb)
  FROM (
    SELECT * FROM notes
    WHERE user_id = p_user
      AND (p_ts IS NULL OR (updated_at, id) > (p_ts, coalesce(p_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    ORDER BY updated_at, id
    LIMIT greatest(1, least(coalesce(p_limit, 200), 500))
  ) n
$fn$;

-- Only the service role (the API, after authenticating the user) may call these.
REVOKE ALL ON FUNCTION notes_apply_mutation(uuid, jsonb)            FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION notes_apply_batch(uuid, jsonb)               FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION notes_pull(uuid, timestamptz, uuid, int)     FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION notes_apply_mutation(uuid, jsonb)         TO service_role;
GRANT EXECUTE ON FUNCTION notes_apply_batch(uuid, jsonb)            TO service_role;
GRANT EXECUTE ON FUNCTION notes_pull(uuid, timestamptz, uuid, int)  TO service_role;

-- ============================================================
