--   DROP FUNCTION IF EXISTS notes_pull(uuid, timestamptz, uuid, int);
--   DROP FUNCTION IF EXISTS notes_apply_batch(uuid, jsonb);
--   DROP FUNCTION IF EXISTS notes_apply_mutation(uuid, jsonb);
--   DROP FUNCTION IF EXISTS notes_canon_labels(text[]);
--   DROP FUNCTION IF EXISTS notes_public(notes);
